WITH flattened AS (SELECT id, plan, tier_value FROM price_tiers LATERAL VIEW EXPLODE(discounts) x AS tier_value) SELECT *, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY tier_value DESC NULLS FIRST) tier_value_percent_rank, MAX(tier_value) OVER (PARTITION BY plan) plan_max_tier_value, COUNT(tier_value) OVER (PARTITION BY plan) plan_count_tier_value FROM flattened WHERE tier_value IS NOT NULL
